import React, { useState } from 'react';

export interface UserProfile {
  id: string;
  name: string;
  avatar: string;
}

interface UserSelectorProps {
  currentUserId: string;
  onUserChange: (userId: string) => void;
  onNewUser: (user: UserProfile) => void;
}

const defaultUsers: UserProfile[] = [
  { id: 'user1', name: '小明', avatar: '👦' },
  { id: 'user2', name: '小红', avatar: '👧' },
  { id: 'user3', name: '小李', avatar: '👨' },
];

const STORAGE_KEY = 'psyqa_users';

export const UserSelector: React.FC<UserSelectorProps> = ({ currentUserId, onUserChange, onNewUser }) => {
  const [showNewUserForm, setShowNewUserForm] = useState(false);
  const [newUserName, setNewUserName] = useState('');
  const [users, setUsers] = useState<UserProfile[]>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (!stored) return defaultUsers;
      const parsed = JSON.parse(stored) as UserProfile[];
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      return defaultUsers;
    } catch {
      return defaultUsers;
    }
  });

  const persistUsers = (nextUsers: UserProfile[]) => {
    setUsers(nextUsers);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(nextUsers));
  };

  const handleAddUser = () => {
    const cleanName = newUserName.trim();
    if (cleanName) {
      const base = cleanName.toLowerCase().replace(/[^a-z0-9\u4e00-\u9fa5]/g, '');
      const newUserId = `user_${base || 'new'}_${Date.now()}`;
      const newUser: UserProfile = {
        id: newUserId,
        name: cleanName,
        avatar: '🙂'
      };
      const nextUsers = [...users, newUser];
      persistUsers(nextUsers);
      onNewUser(newUser);
      setNewUserName('');
      setShowNewUserForm(false);
    }
  };

  return (
    <div className="user-selector">
      <div className="user-selector-title">👤 用户选择</div>
      <div className="user-list">
        {users.map((user) => (
          <div
            key={user.id}
            className={`user-item ${currentUserId === user.id ? 'active' : ''}`}
            onClick={() => onUserChange(user.id)}
          >
            <span className="user-avatar">{user.avatar}</span>
            <span className="user-name">{user.name}</span>
          </div>
        ))}
      </div>

      {!showNewUserForm ? (
        <button className="add-user-btn" onClick={() => setShowNewUserForm(true)}>
          + 添加新用户
        </button>
      ) : (
        <div className="new-user-form">
          <input
            type="text"
            value={newUserName}
            onChange={(e) => setNewUserName(e.target.value)}
            placeholder="输入用户名"
            className="new-user-input"
            autoFocus
          />
          <div className="new-user-actions">
            <button className="submit-btn" onClick={handleAddUser}>确定</button>
            <button className="cancel-btn" onClick={() => setShowNewUserForm(false)}>取消</button>
          </div>
        </div>
      )}
    </div>
  );
};
